@Test
public void closesSqlHandler() {
    jdbcCallback.close();
    verify(sqlHandler, times(1)).close();
}

@Test
public void closeDoesNothingIfSqlHandlerNull() {
    jdbcCallback = new AbstractJdbcCallback(null, cache) {
    };
    jdbcCallback.close();
    verify(sqlHandler, times(0)).close();
}

