@Test
public void whenCCIsNotAvailableAndMemberExists() {
    doReturn(null).when(command).getConfigurationPersistenceService();
    doReturn(Collections.singleton(mock(DistributedMember.class))).when(command).findMembers(null, null);
    ConnectorService.Connection connection1 = new ConnectorService.Connection("name1", "url1", "user1", "password1", "p1:v1,p2:v2");
    ConnectorService.Connection connection2 = new ConnectorService.Connection("name2", "url2", "user2", "password2", "p3:v3,p4:v4");
    ConnectorService.Connection connection3 = new ConnectorService.Connection("name3", "url3", "user3", "password3", "p5:v5,p6:v6");
    ResultCollector rc = mock(ResultCollector.class);
    doReturn(rc).when(command).executeFunction(any(), any(), any(Set.class));
    when(rc.getResult()).thenReturn(Collections.singletonList(new CliFunctionResult("server-1", Stream.of(connection1, connection2, connection3).collect(toSet()), "success")));
    gfsh.executeAndAssertThat(command, COMMAND + " --member=member1").statusIsSuccess().containsOutput("name1", "name2", "name3");
}

