@Test
public void whenCCIsAvailable() {
    doReturn(ccService).when(command).getConfigurationPersistenceService();
    // mappings found in CC
    ConnectorService.RegionMapping mapping1 = new ConnectorService.RegionMapping("region1", "class1", "table1", "name1", true);
    mapping1.getFieldMapping().add(new ConnectorService.RegionMapping.FieldMapping("field1", "value1"));
    ConnectorService.RegionMapping mapping2 = new ConnectorService.RegionMapping("region2", "class2", "table2", "name2", true);
    mapping2.getFieldMapping().add(new ConnectorService.RegionMapping.FieldMapping("field2", "value2"));
    ConnectorService connectorService = new ConnectorService();
    connectorService.getRegionMapping().add(mapping1);
    connectorService.getRegionMapping().add(mapping2);
    when(cacheConfig.findCustomCacheElement(any(), any())).thenReturn(connectorService);
    gfsh.executeAndAssertThat(command, COMMAND).statusIsSuccess().containsOutput("region1", "region2");
}

