    assertThat(fileCopier.getBackupDefinition().getOplogFilesByDiskStore()).containsOnlyKeys(diskStore);
    assertThat(fileCopier.getBackupDefinition().getOplogFilesByDiskStore().get(diskStore)).containsExactlyInAnyOrder(expectedCrfFile, expectedDrfFile, expectedKrfFile);
}

