@Test
public void testSenderStats() throws InterruptedException {
    senderStats.incBatchesRedistributed();
    senderStats.incEventsReceived();
    Mockito.when(sender.getEventQueueSize()).thenReturn(10);
    senderStats.endPut(testStartTime);
    senderStats.endBatch(testStartTime, 100);
    senderStats.incEventsNotQueuedConflated();
    senderStats.incEventsExceedingAlertThreshold();
    sample();
    assertEquals(1, getTotalBatchesRedistributed());
    assertEquals(1, getTotalEventsConflated());
    assertEquals(10, getEventQueueSize());
    assertTrue(getEventsQueuedRate() > 0);
    assertTrue(getEventsReceivedRate() > 0);
    assertTrue(getBatchesDispatchedRate() > 0);
    assertTrue(getAverageDistributionTimePerBatch() > 0);
    assertTrue(getEventsExceedingAlertThreshold() > 0);
}

@Test
public void testFederatingManagerConcurrency() throws Exception {
    serverRule.startServer();
    SystemManagementService service = (SystemManagementService) ManagementService.getExistingManagementService(serverRule.getCache());
    service.createManager();
    FederatingManager manager = service.getFederatingManager();
    MemberMessenger messenger = mock(MemberMessenger.class);
    manager.setMessenger(messenger);
    manager.startManager();
    InternalDistributedMember mockMember = mock(InternalDistributedMember.class);
    when(mockMember.getInetAddress()).thenReturn(InetAddress.getLocalHost());
    when(mockMember.getId()).thenReturn("member-1");
    for (int i = 0; i < 100; i++) {
        manager.addMember(mockMember);
    }
    Awaitility.waitAtMost(1, TimeUnit.SECONDS).until(() -> serverRule.getCache().getAllRegions().size() > 1);
    assertThat(manager.getAndResetLatestException()).isNull();
}

