@Test
public void whenMembersFoundAndClusterConfigRunningThenUpdateClusterConfigAndInvokeFunction() {
    Set<DistributedMember> members = new HashSet<>();
    members.add(mock(DistributedMember.class));
    CliFunctionResult result = new CliFunctionResult("server1", true, "Tried creating jndi binding \"name\" on \"server1\"");
    List<CliFunctionResult> results = new ArrayList<>();
    results.add(result);
    InternalConfigurationPersistenceService clusterConfigService = mock(InternalConfigurationPersistenceService.class);
    CacheConfig cacheConfig = mock(CacheConfig.class);
    doReturn(members).when(command).findMembers(any(), any());
    doReturn(clusterConfigService).when(command).getConfigurationPersistenceService();
    doReturn(results).when(command).executeAndGetFunctionResult(any(), any(), any());
    doReturn(cacheConfig).when(clusterConfigService).getCacheConfig(any());
    doAnswer(invocation -> {
        UnaryOperator<CacheConfig> mutator = invocation.getArgument(1);
        mutator.apply(cacheConfig);
        return null;
    }).when(clusterConfigService).updateCacheConfig(any(), any());
    gfsh.executeAndAssertThat(command, COMMAND + " --type=SIMPLE --name=name --jdbc-driver-class=driver --connection-url=url --datasource-config-properties={'name':'name1','type':'type1','value':'value1'}").statusIsSuccess().tableHasColumnOnlyWithValues("Member", "server1").tableHasColumnOnlyWithValues("Status", "OK").tableHasColumnOnlyWithValues("Message", "Tried creating jndi binding \"name\" on \"server1\"");
    verify(clusterConfigService).updateCacheConfig(any(), any());
    verify(command).updateClusterConfig(eq("cluster"), eq(cacheConfig), any());
    ArgumentCaptor<CreateJndiBindingFunction> function = ArgumentCaptor.forClass(CreateJndiBindingFunction.class);
    ArgumentCaptor<JndiBindingsType.JndiBinding> jndiConfig = ArgumentCaptor.forClass(JndiBindingsType.JndiBinding.class);
    ArgumentCaptor<Set<DistributedMember>> targetMembers = ArgumentCaptor.forClass(Set.class);
    verify(command, times(1)).executeAndGetFunctionResult(function.capture(), jndiConfig.capture(), targetMembers.capture());
    assertThat(function.getValue()).isInstanceOf(CreateJndiBindingFunction.class);
    assertThat(jndiConfig.getValue()).isNotNull();
    assertThat(jndiConfig.getValue().getJndiName()).isEqualTo("name");
    assertThat(jndiConfig.getValue().getConfigProperties().get(0).getName()).isEqualTo("name1");
    assertThat(targetMembers.getValue()).isEqualTo(members);
}

