    command.accumulateListGatewayResult(crd, Collections.EMPTY_MAP, receiverBeans);
    JSONObject tableContent = (JSONObject) crd.retrieveSectionByIndex(0).getSectionGfJsonObject().get("__tables__-GatewayReceiver Table");
