private void createIndexesOnSpy(int numIndexes) {
    LuceneServiceImpl luceneServiceSpy = (LuceneServiceImpl) spy(LuceneServiceProvider.get(ClusterStartupRule.getCache()));
    for (int i = 0; i < numIndexes; i++) {
        luceneServiceSpy.createIndexFactory().setFields("text" + i).create(INDEX_NAME + i, REGION_NAME);
    }
    Answer invokeBeforeAfterDataRegionCreated = invocation -> {
        // Confirm index creation is in progress
        indexCreationInProgress.countDown();
        // Wait for destroy index invocation to complete
        indexDestroyComplete.await();
        return invocation.callRealMethod();
    };
    doAnswer(invokeBeforeAfterDataRegionCreated).when(luceneServiceSpy).afterDataRegionCreated(any());
}

