    when(ctx.getLocalBucketSet((any()))).thenReturn(buckets);
    Awaitility.await().pollDelay(1, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).atMost(500, TimeUnit.SECONDS).until(() -> {
        final Collection<IndexRepository> repositories = new HashSet<>();
