private Result<OQLQueryResponse> invokeHandler(String query, EncodedValue[] bindParameters, ProtobufSerializationService serializer) throws InvalidExecutionContextException, ConnectionStateException, EncodingException, DecodingException {
    final MessageExecutionContext context = mock(MessageExecutionContext.class);
    when(context.getSecureCache()).thenReturn(new SecureCacheImpl((InternalCache) cache, new NoSecurity()));
    final OQLQueryRequest request = OQLQueryRequest.newBuilder().setQuery(query).addAllBindParameter(Arrays.asList(bindParameters)).build();
    Result<OQLQueryResponse> result = new OqlQueryRequestOperationHandler().process(serializer, request, context);
    return result;
}

